if not isinstance(lengths, list) or not isinstance(alphabet_sizes, list):
    return (False, None)
if len(lengths) != num_blocks or len(alphabet_sizes) != num_blocks:
    return (False, None)
# Domain constraints to enforce difficulty and well-posedness
if not (3 <= num_blocks <= 6):
    return (False, None)
if not (2 <= target_k <= num_blocks - 1):
    return (False, None)
for L in lengths:
    if not isinstance(L, int) or L < 2:
        return (False, None)
for s in alphabet_sizes:
    if not isinstance(s, int) or s < 2:
        return (False, None)
# Compute per-block palindrome probabilities: p_i = s_i^{-floor(L_i/2)}
try:
    ps = [Fraction(1, (s ** (L // 2))) for L, s in zip(lengths, alphabet_sizes)]
except Exception:
    return (False, None)
# Enforce non-triviality: not all p_i identical
if len(set(ps)) <= 1:
    return (False, None)
