dp = [Fraction(0, 1)] * (num_blocks + 1)
dp[0] = Fraction(1, 1)
for p in ps:
    new_dp = [Fraction(0, 1)] * (num_blocks + 1)
    for k in range(num_blocks + 1):
        new_dp[k] += dp[k] * (Fraction(1, 1) - p)
        if k > 0:
            new_dp[k] += dp[k - 1] * p
    dp = new_dp
prob = dp[target_k]
# Ensure probability is strictly between 0 and 1
if prob <= 0 or prob >= 1:
    return (False, None)
# Reduce fraction and compute m + n
prob = prob  # already a Fraction
m = prob.numerator
n = prob.denominator
# Basic sanity: m and n positive and coprime by Fraction properties
if m <= 0 or n <= 0:
    return (False, None)
answer = m + n
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

